head.script:
///////// 1. 변수 및 선언 영역 /////////

scwin.pageId = "ULDTMS03130";
scwin.scrollTop = "";

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 재진입 시 저장된 검색 조건·스크롤 위치(storageId)를 복원하고 서식권한 목록을 조회한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        const storageId = $c.data.getParameter("storageId");

        if (!$c.util.isEmpty(storageId)) {
            scwin.scrollTop = $c.tms.getKeywordSave(storageId, dma_search);
        }
        // 조회
        scwin.fnSearch();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDTMS03130.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_search_onclick
 * @description [조회] 버튼 클릭 — 서식권한 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_search_onclick(e);
 */
scwin.btn_search_onclick = function (e) {
    scwin.fnSearch();
};

/**
 * @method
 * @name ibx_keyword_onkeyup
 * @description 검색어 입력 — Enter 키 입력 시 서식권한 목록을 조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_keyword_onkeyup(e);
 */
scwin.ibx_keyword_onkeyup = function (e) {
    if (e.key === "Enter") {
        scwin.fnSearch();
    }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description 목록 셀 클릭 — 권한ID 컬럼 클릭 시 현재 검색 조건·위치를 저장하고 선택 행의 권한 정보로 서식권한 상세 화면(ULDTMS03150)으로 이동한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 열 인덱스
 * @param {String} columnId 클릭한 컬럼 ID
 * @returns {void}
 * @hidden N
 * @example scwin.grd_list_oncellclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    if (columnId === "authId") {
        const url_ = "/ui/TMS/ULDTMS03150.xml";

        // 위치 정보 저장
        $c.tms.setKeywordSave(scwin.pageId, grd_list, dma_search);

        const params = {};
        params.authId = dlt_list.getCellData(rowIndex, "authId");
        params.authNm = dlt_list.getCellData(rowIndex, "authNm");
        params.authDsc = dlt_list.getCellData(rowIndex, "authDsc");
        params.storageId = scwin.pageId;

        $c.win.moveUrl(url_, params);
    }
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_list_submitdone
 * @description 서식권한 목록 조회(sbm_list) 완료 콜백 — 조회 성공 시 총 건수를 표시하고 저장된 스크롤 위치를 복원한다. 실패 시 오류 메시지를 알린다.
 * @param {Object} e 서브미션 응답 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_list ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_list_submitdone = function (e) {
    // 조회 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        // 총 건수
        tbx_totCnt.setValue($c.num.formatNumber(dlt_list.getRowCount()));

        // 재조회 여부 체크
        if (!$c.util.isEmpty(scwin.scrollTop)) {
            grd_list.setScrollTop(scwin.scrollTop);
            scwin.scrollTop = "";
        }
    } else {
        $c.win.alert(result.message);
    }
};

///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name fnSearch
 * @description 서식권한 목록 조회 — 검색 조건(dma_search)으로 sbm_list 를 실행한다.
 * @returns {void}
 * @hidden N
 * @example scwin.fnSearch();
 */
scwin.fnSearch = function () {
    // 조회
    $c.sbm.execute(sbm_list, dma_search.getJSON());
};
